-- Generated by scripts/sync_cultivation.mjs; preserve every user's EXP.
BEGIN;
ALTER TABLE users ALTER COLUMN cultivation_realm SET DEFAULT 'Phàm Nhân';
WITH recalculated AS (
  SELECT id, CASE
    WHEN COALESCE(cultivation_exp, 0) >= 20000000 THEN 'Tiên Đế'
    WHEN COALESCE(cultivation_exp, 0) >= 17000000 THEN 'Chuẩn Tiên Đế'
    WHEN COALESCE(cultivation_exp, 0) >= 14000000 THEN 'Tiên Tôn'
    WHEN COALESCE(cultivation_exp, 0) >= 11000000 THEN 'Tiên Vương'
    WHEN COALESCE(cultivation_exp, 0) >= 8500000 THEN 'Tiên Quân'
    WHEN COALESCE(cultivation_exp, 0) >= 7400000 THEN 'Đại La Kim Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 6600000 THEN 'Thái Ất Kim Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 5850000 THEN 'Kim Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 5150000 THEN 'Huyền Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 4500000 THEN 'Chân Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 3900000 THEN 'Thiên Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 3350000 THEN 'Địa Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 2850000 THEN 'Nhân Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 2400000 THEN 'Bán Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 2000000 THEN 'Độ Kiếp'
    WHEN COALESCE(cultivation_exp, 0) >= 1650000 THEN 'Đại Thừa'
    WHEN COALESCE(cultivation_exp, 0) >= 1350000 THEN 'Hợp Đạo'
    WHEN COALESCE(cultivation_exp, 0) >= 1100000 THEN 'Hợp Thể'
    WHEN COALESCE(cultivation_exp, 0) >= 900000 THEN 'Luyện Hư'
    WHEN COALESCE(cultivation_exp, 0) >= 720000 THEN 'Hóa Thần'
    WHEN COALESCE(cultivation_exp, 0) >= 560000 THEN 'Xuất Khiếu'
    WHEN COALESCE(cultivation_exp, 0) >= 420000 THEN 'Nguyên Anh'
    WHEN COALESCE(cultivation_exp, 0) >= 300000 THEN 'Kết Đan'
    WHEN COALESCE(cultivation_exp, 0) >= 210000 THEN 'Trúc Cơ'
    WHEN COALESCE(cultivation_exp, 0) >= 140000 THEN 'Luyện Khí'
    WHEN COALESCE(cultivation_exp, 0) >= 90000 THEN 'Võ Thần'
    WHEN COALESCE(cultivation_exp, 0) >= 55000 THEN 'Lục Địa Thần Tiên'
    WHEN COALESCE(cultivation_exp, 0) >= 30000 THEN 'Thiên Nhân'
    WHEN COALESCE(cultivation_exp, 0) >= 15000 THEN 'Đại Tông Sư'
    WHEN COALESCE(cultivation_exp, 0) >= 7000 THEN 'Tông Sư'
    WHEN COALESCE(cultivation_exp, 0) >= 3000 THEN 'Tiên Thiên'
    WHEN COALESCE(cultivation_exp, 0) >= 1200 THEN 'Hậu Thiên'
    WHEN COALESCE(cultivation_exp, 0) >= 300 THEN 'Luyện Thể'
    WHEN COALESCE(cultivation_exp, 0) >= 0 THEN 'Phàm Nhân'
  END AS realm FROM users
)
UPDATE users u SET cultivation_realm = r.realm
FROM recalculated r WHERE u.id = r.id AND u.cultivation_realm IS DISTINCT FROM r.realm;
COMMIT;
